const sources = $input.all();
const results = [];
const MAX_PAGES = 5;

for (let si = 0; si < sources.length; si++) {
  const s = sources[si].json;
  const url = s.url || '';
  const noPagination = url.includes('quintoandar.com.br');
  const maxP = noPagination ? 1 : MAX_PAGES;
  for (let p = 1; p <= maxP; p++) {
    let pageUrl = url;
    if (p > 1) {
      if (url.includes('olx.com.br')) pageUrl = url + '&o=' + p;
      else if (url.includes('zapimoveis.com.br')) pageUrl = url + '&pagina=' + p;
      else if (url.includes('dfimoveis.com.br')) pageUrl = url + '?pagina=' + p;
      else if (url.includes('rentola.com.br')) pageUrl = url + '?page=' + p;
      else if (url.includes('imovelweb.com.br')) pageUrl = url.replace('.html', '-pagina-' + p + '.html');
      else pageUrl = url + '?page=' + p;
    }
    results.push({
      json: { url: pageUrl, nome: s.nome || '', metodo: s.metodo || 'html_json_ld', regiao: s.regiao || '', url_original: url, pagina: p },
      pairedItem: { item: si }
    });
  }
}
return results;

const allPages = $input.all();
const agora = new Date().toISOString();
const PRECO_MAX = 1800;

function hashStr(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = Math.imul(31, h) + str.charCodeAt(i) | 0; }
  return Math.abs(h).toString(16).padStart(8, '0');
}

function toNum(val) {
  if (val === null || val === undefined || val === '') return 0;
  const s = String(val).replace('R$', '').replace(/[^0-9,]/g, '').replace(',', '.');
  const n = parseFloat(s);
  return (isNaN(n) || n < 0) ? 0 : n;
}

function getStr(obj, key) {
  return (obj && obj[key] !== undefined && obj[key] !== null) ? String(obj[key]) : '';
}

function getAction(obj) {
  const action = obj.potentialAction;
  if (!action) return 0;
  const arr = Array.isArray(action) ? action : [action];
  for (let i = 0; i < arr.length; i++) {
    const a = arr[i];
    if (a.price !== undefined && a.price !== null && a.price !== '') {
      const p = toNum(a.price);
      if (p > 0) return p;
    }
  }
  return 0;
}

function getPrice(obj) {
  if (!obj) return 0;
  const offers = obj.offers || {};
  let p;
  p = toNum(offers.price); if (p > 0) return p;
  p = toNum(offers.lowPrice); if (p > 0) return p;
  if (offers.priceSpecification) {
    const ps = Array.isArray(offers.priceSpecification) ? offers.priceSpecification[0] : offers.priceSpecification;
    p = toNum(ps && ps.price); if (p > 0) return p;
  }
  p = toNum(obj.price); if (p > 0) return p;
  p = getAction(obj); if (p > 0) return p;
  return 0;
}

function getDate(obj) {
  const offers = obj && (obj.offers || {});
  return getStr(obj, 'datePosted') ||
         getStr(obj, 'datePublished') ||
         getStr(obj, 'dateCreated') ||
         (offers ? getStr(offers, 'validFrom') : '') ||
         (offers ? getStr(offers, 'availabilityStarts') : '') || '';
}

function parseAddress(addrVal) {
  if (!addrVal) return { streetAddress: '', addressLocality: '' };
  if (typeof addrVal === 'string') {
    const parts = addrVal.split(',').map(function(p) { return p.trim(); });
    return { streetAddress: parts[0] || '', addressLocality: parts[1] || '' };
  }
  return { streetAddress: getStr(addrVal, 'streetAddress'), addressLocality: getStr(addrVal, 'addressLocality') };
}

function parseFloor(val) {
  if (!val) return 0;
  if (typeof val === 'number') return val;
  if (typeof val === 'object' && val.value) return parseFloat(val.value) || 0;
  return parseFloat(String(val)) || 0;
}

function priceFromDesc(desc) {
  const m = String(desc || '').match(/[Aa]luguel[^:]*:\s*[R][\u0024]\s*([\d.,]+)/);
  return m ? toNum(m[1]) : 0;
}

function extractItems(obj, regiao) {
  const out = [];
  if (!obj || typeof obj !== 'object') return out;
  const type = getStr(obj, '@type') || getStr(obj, 'type');

  if (type.includes('RealEstate') || type === 'Apartment') {
    const mainArr = obj.mainEntity ? (Array.isArray(obj.mainEntity) ? obj.mainEntity : [obj.mainEntity]) : null;
    if (mainArr && mainArr.length > 0) {
      const topOffers = obj.offers || {};
      const aggPrice = toNum(topOffers.lowPrice || topOffers.price || 0);
      for (let i = 0; i < mainArr.length; i++) {
        const item = mainArr[i];
        const t2 = getStr(item, '@type') || getStr(item, 'type');
        if (!t2.includes('RealEstate') && t2 !== 'Apartment') continue;
        const iOff = item.offers || {};
        const cLoc = item.contentLocation || {};
        const addr = parseAddress(item.address);
        const desc = getStr(item, 'description');
        const preco = getPrice(item) || priceFromDesc(desc) || aggPrice;
        const entry = {
          titulo: (desc || getStr(item, 'name') || '').substring(0, 150).split('\n')[0].trim(),
          preco_raw: preco,
          link: getStr(item, 'url') || getStr(iOff, 'url') || '',
          imagem: Array.isArray(item.image) ? (item.image[0] || '') : getStr(item, 'image'),
          descricao: desc,
          quartos: parseInt(item.numberOfBedrooms || 0) || 0,
          banheiros: parseInt(item.numberOfFullBathrooms || item.numberOfBathroomsTotal || item.numberOfBathrooms || 0) || 0,
          metragem: parseFloor(item.floorSize),
          bairro: getStr(cLoc, 'name') || addr.addressLocality || regiao,
          endereco: addr.streetAddress,
          data_anuncio: getStr(item, 'datePosted') || getStr(item, 'datePublished') || getStr(item, 'dateCreated') || ''
        };
        if (entry.titulo || entry.link) out.push(entry);
      }
    } else {
      const offers = obj.offers || {};
      const prop = offers.itemOffered || obj;
      const addr = parseAddress(obj.address);
      const preco = getPrice(obj);
      const entry = {
        titulo: getStr(obj, 'name'),
        preco_raw: preco,
        link: getStr(obj, 'url') || getStr(offers, 'url') || '',
        imagem: Array.isArray(obj.image) ? (obj.image[0] || '') : getStr(obj, 'image'),
        descricao: getStr(obj, 'description') || getStr(prop, 'description'),
        quartos: parseInt(prop.numberOfBedrooms || obj.numberOfBedrooms || 0) || 0,
        banheiros: parseInt(prop.numberOfFullBathrooms || prop.numberOfBathroomsTotal || prop.numberOfBathrooms || obj.numberOfFullBathrooms || obj.numberOfBathroomsTotal || obj.numberOfBathrooms || 0) || 0,
        metragem: parseFloor(prop.floorSize || obj.floorSize),
        bairro: addr.addressLocality || regiao,
        endereco: addr.streetAddress,
        data_anuncio: getDate(obj)
      };
      if (entry.titulo || entry.link) out.push(entry);
    }
  } else if (type === 'Product') {
    const offers = obj.offers || {};
    const preco = toNum(offers.price || offers.lowPrice || obj.price || 0);
    const entry = {
      titulo: getStr(obj, 'name'),
      preco_raw: preco,
      link: getStr(offers, 'url') || getStr(obj, 'url') || '',
      imagem: Array.isArray(obj.image) ? (obj.image[0] || '') : getStr(obj, 'image'),
      descricao: getStr(obj, 'description'),
      quartos: 0, banheiros: 0, metragem: 0,
      bairro: regiao, endereco: '', data_anuncio: getDate(obj)
    };
    if (entry.titulo || entry.link) out.push(entry);
  } else {
    if (obj.itemListElement) {
      const arr = Array.isArray(obj.itemListElement) ? obj.itemListElement : [obj.itemListElement];
      for (let j = 0; j < arr.length; j++) {
        const found = extractItems(arr[j].item || arr[j], regiao);
        for (let k = 0; k < found.length; k++) out.push(found[k]);
      }
    }
    if (obj.mainEntity) {
      const arr2 = Array.isArray(obj.mainEntity) ? obj.mainEntity : [obj.mainEntity];
      for (let mi = 0; mi < arr2.length; mi++) {
        const found2 = extractItems(arr2[mi], regiao);
        for (let ni = 0; ni < found2.length; ni++) out.push(found2[ni]);
      }
    }
  }
  return out;
}

const byUrl = {};

for (let pi = 0; pi < allPages.length; pi++) {
  const page = allPages[pi];
  const html = page.json.data || '';
  const metodo = page.json.src_metodo || 'html_json_ld';
  const siteOrigem = page.json.src_nome || '';
  const regiao = page.json.src_regiao || '';

  if (!html || typeof html !== 'string' || html.length < 200) continue;
  if (html.includes('Cloudflare') && (html.includes('blocked') || html.includes('Just a moment'))) continue;

  const raw = [];

  if (metodo === 'json_embutido') {
    const idx = html.indexOf('<script id="__NEXT_DATA__"');
    if (idx >= 0) {
      const start = html.indexOf('>', idx) + 1;
      const end = html.indexOf('</script>', start);
      if (start > 0 && end > start) {
        try {
          const d = JSON.parse(html.substring(start, end));
          const pp = (d.props || {}).pageProps || {};
          const ads = pp.ads || ((pp.listingProps || {}).adList) || pp.adList || [];
          for (let ai = 0; ai < ads.length; ai++) {
            const a = ads[ai];
            const loc = a.location || {};
            const imgs = a.images || [];
            raw.push({
              titulo: a.subject || getStr(a, 'title') || '',
              preco_raw: toNum(a.priceValue),
              bairro: getStr(loc, 'neighbourhood') || getStr(loc, 'zone') || getStr(loc, 'city') || regiao,
              link: getStr(a, 'url') || getStr(a, 'friendlyUrl') || '',
              imagem: (imgs[0] || {}).originalImage || '',
              descricao: getStr(a, 'body') || '',
              data_anuncio: a.listTime ? new Date(a.listTime * 1000).toISOString() : '',
              quartos: parseInt(a.rooms) || 0,
              metragem: parseFloat(a.size) || 0,
              banheiros: 0, endereco: ''
            });
          }
        } catch(e) {}
      }
    }
  } else if (metodo !== 'playwright') {
    const re = /<script[^>]*type=["']application\/ld[+]json["'][^>]*>([\s\S]*?)<\/script>/gi;
    let ldMatch;
    while ((ldMatch = re.exec(html)) !== null) {
      try {
        const d = JSON.parse(ldMatch[1]);
        const tops = Array.isArray(d) ? d : [d];
        for (let ti = 0; ti < tops.length; ti++) {
          const found = extractItems(tops[ti], regiao);
          for (let fi = 0; fi < found.length; fi++) raw.push(found[fi]);
        }
      } catch(e) {}
    }
  }

  for (let ri = 0; ri < raw.length; ri++) {
    const l = raw[ri];
    if (!l.link || !l.titulo) continue;
    const preco = l.preco_raw || 0;
    const urlKey = l.link.split('?')[0].split('#')[0];
    if (byUrl[urlKey]) {
      if (preco > byUrl[urlKey].preco_raw) {
        byUrl[urlKey] = Object.assign({}, l, { siteOrigem: siteOrigem, regiao: regiao });
      }
      continue;
    }
    byUrl[urlKey] = Object.assign({}, l, { siteOrigem: siteOrigem, regiao: regiao });
  }
}

const results = [];
const urlKeys = Object.keys(byUrl);

for (let ui = 0; ui < urlKeys.length; ui++) {
  const l = byUrl[urlKeys[ui]];
  const preco = l.preco_raw || 0;
  if (preco <= 0 || preco > PRECO_MAX) continue;
  const desc = (l.titulo + ' ' + (l.descricao || '')).toLowerCase();
  const vaga = desc.includes('vaga') || desc.includes('garagem');
  const mobiliado = desc.includes('mobiliado') || desc.includes('mobiliada');
  const tags = [];
  if (preco <= 1500) tags.push('abaixo_orcamento');
  tags.push('total_ate_1800');
  if (vaga) tags.push('vaga');
  if (mobiliado) tags.push('mobiliado');
  if (preco <= 1500 && vaga) tags.push('boa_oportunidade');
  tags.push('anuncio_novo');
  const out = {};
  out.hash = hashStr(urlKeys[ui]);
  out.titulo = l.titulo.substring(0, 200);
  out.preco_aluguel = preco;
  out.condominio = 0;
  out.total_estimado = preco;
  out.bairro = l.bairro || l.regiao;
  out.regiao = l.regiao;
  out.endereco = l.endereco || '';
  out.quartos = l.quartos || 0;
  out.banheiros = l.banheiros || 0;
  out.metragem = l.metragem || 0;
  out.vaga = vaga ? 'TRUE' : 'FALSE';
  out.descricao = (l.descricao || '').substring(0, 500);
  out.link = l.link;
  out.imagem_principal = l.imagem || '';
  out.anunciante = '';
  out.telefone = '';
  out.whatsapp = '';
  out.site_origem = l.siteOrigem;
  out.data_coleta = agora;
  out.data_anuncio = l.data_anuncio || '';
  out.data_atualizacao = agora;
  out.tags = tags.join(',');
  out.status = 'novo';
  out.destaque = 'FALSE';
  results.push({ json: out });
}

if (results.length === 0) {
  return [{ json: { _info: 'nenhum anuncio encontrado' } }];
}
return results;
